/* viscosity–temperature curves by the Walther relation log log (ν + 0.7) = A − B log T (T in kelvin), fitted through
   68 cSt at 40 °C for both oils and 8.6 cSt (oil A, VI about 95) or 10.4 cSt (oil B, VI about 150) at 100 °C */
const MD_walther=(v40,v100)=>{const L=v=>Math.log10(Math.log10(v+0.7)),t1=Math.log10(313.15),t2=Math.log10(373.15),B=(L(v40)-L(v100))/(t2-t1),A=L(v40)+B*t1;
 return T=>Math.pow(10,Math.pow(10,A-B*Math.log10(T+273.15)))-0.7};
